import{_ as e,c as a,o,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"es/blog/inner-critic.md","filePath":"es/blog/inner-critic.md"}');const r=e({name:"es/blog/inner-critic.md"},[["render",function(e,i,r,t,l,s){return o(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="entendiendo-al-critico-interno" tabindex="-1">Entendiendo al crítico interno <a class="header-anchor" href="#entendiendo-al-critico-interno" aria-label="Permalink to &quot;Entendiendo al crítico interno&quot;">​</a></h1><p>Todo jugador de petanca conoce esa voz. La que susurra &quot;vas a fallar&quot; justo cuando estás a punto de lanzar. La que repite tu último tiro fallido en un bucle infinito. Es tu crítico interior, y aprender a controlarlo es esencial para un rendimiento de élite.</p><h2 id="¿que-es-el-critico-interno" tabindex="-1">¿Qué es el crítico interno? <a class="header-anchor" href="#¿que-es-el-critico-interno" aria-label="Permalink to &quot;¿Qué es el crítico interno?&quot;">​</a></h2><p>El crítico interno es esa voz interior que juzga, critica y mina tu confianza. En la petanca, suele aparecer en los peores momentos:</p><ul><li><strong>Antes de un disparo crucial</strong>: &quot;Todos están mirando. No arruines esto&quot;.</li><li><strong>Después de un fallo</strong>: &quot;Siempre te ahogas bajo presión&quot;.</li><li><strong>Durante una racha perdedora</strong>: &quot;No eres lo suficientemente bueno para este nivel&quot;.</li></ul><p>Esta voz no intenta hacerte daño; en realidad, es un intento erróneo de protección. Tu cerebro intenta prepararte para el fracaso para que no te duela tanto. Pero esta &quot;protección&quot; se convierte en autosabotaje.</p><h2 id="reconociendo-tus-patrones" tabindex="-1">Reconociendo tus patrones <a class="header-anchor" href="#reconociendo-tus-patrones" aria-label="Permalink to &quot;Reconociendo tus patrones&quot;">​</a></h2><p>El primer paso es la consciencia. Empieza a notar cuándo aparece tu crítico interior:</p><h3 id="desencadenantes-comunes" tabindex="-1">Desencadenantes comunes <a class="header-anchor" href="#desencadenantes-comunes" aria-label="Permalink to &quot;Desencadenantes comunes&quot;">​</a></h3><ul><li>Situaciones de alta presión (punto de partido, torneos importantes)</li><li>Después de cometer un error</li><li>Cuando los oponentes tienen un buen desempeño</li><li>Cuando los compañeros de equipo parecen frustrados</li><li>Fatiga física o malestar</li></ul><h3 id="mensajes-comunes" tabindex="-1">Mensajes comunes <a class="header-anchor" href="#mensajes-comunes" aria-label="Permalink to &quot;Mensajes comunes&quot;">​</a></h3><ul><li>&quot;No puedes soportar la presión&quot;</li><li>&quot;No eres tan bueno como ellos&quot;</li><li>&quot;Todo el mundo te está juzgando&quot;</li><li>&quot;Siempre fallas cuando importa&quot;</li></ul><h2 id="el-impacto-en-el-rendimiento" tabindex="-1">El impacto en el rendimiento <a class="header-anchor" href="#el-impacto-en-el-rendimiento" aria-label="Permalink to &quot;El impacto en el rendimiento&quot;">​</a></h2><p>Cuando el crítico interno toma el control, tu cuerpo responde:</p><ol><li><strong>La tensión muscular aumenta</strong> — Tu lanzamiento se vuelve rígido</li><li><strong>La respiración se vuelve superficial</strong> — Menos oxígeno, menos concentración</li><li><strong>La visión se estrecha</strong> — Pierdes la conciencia del terreno</li><li><strong>La toma de decisiones se ve afectada</strong> — Dudas de ti mismo</li></ol><p>Esto crea un círculo vicioso: el crítico interno provoca un mal desempeño, lo que le da más munición.</p><h2 id="estrategias-para-gestionar-al-critico-interno" tabindex="-1">Estrategias para gestionar al crítico interno <a class="header-anchor" href="#estrategias-para-gestionar-al-critico-interno" aria-label="Permalink to &quot;Estrategias para gestionar al crítico interno&quot;">​</a></h2><h3 id="_1-ponle-un-nombre-para-domarlo" tabindex="-1">1. Ponle un nombre para domarlo <a class="header-anchor" href="#_1-ponle-un-nombre-para-domarlo" aria-label="Permalink to &quot;1. Ponle un nombre para domarlo&quot;">​</a></h3><p>Ponle un nombre a tu crítico interno, algo un poco ridículo. &quot;¡Ah, ahí va otra vez Negativo Nils!&quot;. Esto crea distancia entre tú y la voz, facilitando su desestimación.</p><h3 id="_2-cuestionar-la-evidencia" tabindex="-1">2. Cuestionar la evidencia <a class="header-anchor" href="#_2-cuestionar-la-evidencia" aria-label="Permalink to &quot;2. Cuestionar la evidencia&quot;">​</a></h3><p>Cuando el crítico dice &quot;siempre fallas bajo presión&quot;, pregúntate: ¿Es cierto? ¿Recuerdas momentos en los que te fue bien bajo presión? El crítico usa absolutos que rara vez reflejan la realidad.</p><h3 id="_3-reformular-el-mensaje" tabindex="-1">3. Reformular el mensaje <a class="header-anchor" href="#_3-reformular-el-mensaje" aria-label="Permalink to &quot;3. Reformular el mensaje&quot;">​</a></h3><p>Transformar la crítica en coaching:</p><ul><li>&quot;Lo vas a extrañar&quot; → &quot;Concéntrate en tu rutina&quot;</li><li>&quot;Todos están mirando&quot; → &quot;Este es tu momento para brillar&quot;</li><li>&quot;Siempre te ahogas&quot; → &quot;Ya has manejado la presión antes&quot;</li></ul><h3 id="_4-utilice-su-rutina-previa-al-disparo" tabindex="-1">4. Utilice su rutina previa al disparo <a class="header-anchor" href="#_4-utilice-su-rutina-previa-al-disparo" aria-label="Permalink to &quot;4. Utilice su rutina previa al disparo&quot;">​</a></h3><p>Una <a href="/es/educacion/fuerza-mental/rutina-pre-disparo">rutina previa al disparo</a> sólida le da a tu mente algo constructivo en lo que concentrarse, dejando menos espacio para la crítica.</p><h3 id="_5-practica-la-autocompasion" tabindex="-1">5. Practica la autocompasión <a class="header-anchor" href="#_5-practica-la-autocompasion" aria-label="Permalink to &quot;5. Practica la autocompasión&quot;">​</a></h3><p>Trátate como a un compañero de equipo. ¿Le dirías a un compañero con dificultades &quot;eres terrible&quot;? Claro que no. Sé amable contigo mismo.</p><h2 id="construyendo-una-voz-interior-de-apoyo" tabindex="-1">Construyendo una voz interior de apoyo <a class="header-anchor" href="#construyendo-una-voz-interior-de-apoyo" aria-label="Permalink to &quot;Construyendo una voz interior de apoyo&quot;">​</a></h2><p>El objetivo no es silenciar por completo a la crítica interna; eso es casi imposible. En cambio, desarrolla una voz de apoyo más fuerte:</p><h3 id="la-voz-de-apoyo-dice" tabindex="-1">La voz de apoyo dice: <a class="header-anchor" href="#la-voz-de-apoyo-dice" aria-label="Permalink to &quot;La voz de apoyo dice:&quot;">​</a></h3><ul><li>&quot;Un lanzamiento a la vez&quot;</li><li>&quot;Confía en tu entrenamiento&quot;</li><li>&quot;Ya has hecho esto antes&quot;</li><li>&quot;Quédate en el presente&quot;</li><li>&quot;Respira y reinicia&quot;</li></ul><h3 id="practica-diaria" tabindex="-1">Práctica diaria <a class="header-anchor" href="#practica-diaria" aria-label="Permalink to &quot;Práctica diaria&quot;">​</a></h3><p>Dedica 5 minutos cada día a:</p><ol><li>Recuerda un momento en el que te desempeñaste bien</li><li>Recuerda cómo te sentiste en el cuerpo</li><li>Escuche lo que decía su voz de apoyo</li><li>Ancla este sentimiento con un gesto físico (tocar tu bola, ajustar tu postura)</li></ol><h2 id="en-competicion" tabindex="-1">En competición <a class="header-anchor" href="#en-competicion" aria-label="Permalink to &quot;En competición&quot;">​</a></h2><p>Cuando el crítico interior aparece durante un partido:</p><ol><li><strong>Reconócelo</strong>: &quot;Me doy cuenta de que estoy siendo autocrítico&quot;</li><li><strong>Toma una respiración</strong>: Respira lenta y profundamente para reiniciar.</li><li><strong>Usa tu ancla</strong>: El gesto físico de tu práctica</li><li><strong>Vuelve a la rutina</strong>: Concéntrate en tu proceso previo a la inyección</li></ol><h2 id="el-viaje-a-largo-plazo" tabindex="-1">El viaje a largo plazo <a class="header-anchor" href="#el-viaje-a-largo-plazo" aria-label="Permalink to &quot;El viaje a largo plazo&quot;">​</a></h2><p>Gestionar la crítica interna no es una solución única. Es una práctica continua que se vuelve más fácil con el tiempo. Los jugadores de élite no eliminan las dudas, sino que aprenden a rendir a pesar de ellas.</p><p>El crítico interior siempre será parte de ti. Pero con la práctica, su voz se aquieta y tu voz de apoyo se fortalece. Esa es la ventaja mental que distingue a los buenos jugadores de los grandes.</p><hr><p>| <em>Relacionado: <a href="/es/educacion/fuerza-mental/manejo-de-la-presion">Manejo de la presión</a> | <a href="/es/educacion/fuerza-mental/rutina-pre-disparo">Rutina pre-disparo</a> | <a href="/es/educacion/atención/técnicas">Técnicas de atención plena</a></em> |</p>',43)])])}]]);export{i as __pageData,r as default};
